void FPGA::SetNumberOfPoints(uint16_t npoints) {
	// register has to be set to number of points - 1
	npoints--;
	WriteRegister(Reg::SweepPoints, npoints);
}

void FPGA::SetSamplesPerPoint(uint32_t nsamples) {
	// register is in multiples of 16
	nsamples /= 16;
	// constrain to maximum value
	if(nsamples >= 8192) {
		nsamples = 8191;
	}
	WriteRegister(Reg::SamplesPerPoint, nsamples);
}

void FPGA::SetSettlingTime(uint16_t us) {
	// register is in multiples of 1/102.4 MHz
	uint32_t value = (uint32_t) us * 512 / 5;
	constexpr uint32_t maxval = 0xFFFFF;
	if(value > maxval) {
		value = maxval;
	}
	WriteRegister(Reg::SettlingTimeLow, value & 0xFFFF);
	WriteRegister(Reg::SettlingTimeHigh, value >> 16);
}

void FPGA::SetupSweep(uint8_t stages, uint8_t port1_stage, uint8_t port2_stage, bool synchronize, bool syncMaster) {
	uint16_t value = 0x0000;
	value |= (uint16_t) (stages & 0x07) << 13;
	if(synchronize) {
		value |= 0x1000;
	}
	value |= (port1_stage & 0x07) << 3;
	value |= (port2_stage & 0x07) << 0;
	WriteRegister(Reg::SweepSetup, value);
	Enable(Periphery::SyncMaster, syncMaster);
}

